package com.bobbuy.service;
import com.bobbuy.model.*;
import com.bobbuy.repository.*;
import com.bobbuy.api.response.ApiException;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class ProductMarkerServiceTest {
 ProductMarkerDefinitionRepository definitions=mock(ProductMarkerDefinitionRepository.class);ProductMarkerSetRepository sets=mock(ProductMarkerSetRepository.class);ProductRepository products=mock(ProductRepository.class);UserRepository users=mock(UserRepository.class);
 PublicProductCatalogService catalog=mock(PublicProductCatalogService.class);
 ProductMarkerService service=new ProductMarkerService(definitions,sets,products,users,catalog);
 @BeforeEach void setup(){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("agent-1",null,List.of(new SimpleGrantedAuthority("ROLE_AGENT"))));when(users.lockById(1L)).thenReturn(Optional.of(new User()));}
 @AfterEach void clearContext(){SecurityContextHolder.clearContext();}
 Product product(String id,long owner,ProductVisibility visibility){var p=new Product();p.setId(id);p.setMerchantId(owner);p.setVisibilityStatus(visibility);return p;}
 ProductMarkerDefinition marker(String id,long owner,boolean enabled,int order){var d=new ProductMarkerDefinition();d.id=id;d.merchantId=owner;d.code="new";d.badge="新";d.name=Map.of("ja-JP","新商品","zh-CN","新品","zh-TW","新品","en-US","New");d.description=Map.of();d.color="green";d.enabled=enabled;d.sortOrder=order;d.version=0L;return d;}
 ProductMarkerService.Input input(String badge,String color){return new ProductMarkerService.Input("new",badge,marker("x",1,true,0).name,Map.of(),color,0,true,null);}
 @Test void noRoleCannotReadOrMutateDefinitions(){SecurityContextHolder.clearContext();assertThatThrownBy(()->service.definitions()).isInstanceOf(ApiException.class);assertThatThrownBy(()->service.save(null,input("新","green"))).isInstanceOf(ApiException.class);verifyNoInteractions(definitions,sets,products);}
 @Test void badgeColorAndFourLocaleValidationFailClosed(){for(var i:List.of(input("xx","green"),input("<","red"),input("新","url(red)"),input("新",null),new ProductMarkerService.Input("new","新",Map.of("ja-JP","新商品"),Map.of(),"green",0,true,null))){assertThatThrownBy(()->service.save(null,i)).isInstanceOf(ApiException.class);}verifyNoInteractions(definitions,sets,products,users);}
 @Test void ownerCannotAssignOtherOwnersProduct(){when(products.findById("p")).thenReturn(Optional.of(product("p",2,ProductVisibility.PUBLIC)));assertThatThrownBy(()->service.assign("p",List.of(),0)).isInstanceOf(ApiException.class);verifyNoInteractions(sets,definitions);}
 @Test void unknownAndForeignDefinitionsAreRejected(){when(products.findById("p")).thenReturn(Optional.of(product("p",1,ProductVisibility.PUBLIC)));when(definitions.findAllById(List.of("unknown"))).thenReturn(List.of());assertThatThrownBy(()->service.assign("p",List.of("unknown"),0)).isInstanceOf(ApiException.class);when(definitions.findAllById(List.of("foreign"))).thenReturn(List.of(marker("foreign",2,true,0)));assertThatThrownBy(()->service.assign("p",List.of("foreign"),0)).isInstanceOf(ApiException.class);verifyNoInteractions(sets);}
 @Test void sameSetRetryIsNoOpButDifferentStaleSetFails(){when(products.findById("p")).thenReturn(Optional.of(product("p",1,ProductVisibility.PUBLIC)));var set=new ProductMarkerSet();set.productId="p";set.merchantId=1L;set.markerIds=List.of("new");set.version=3L;when(sets.findById("p")).thenReturn(Optional.of(set));when(definitions.findAllById(List.of("new"))).thenReturn(List.of(marker("new",1,true,0)));assertThat(service.assign("p",List.of("new"),0).version()).isEqualTo(4);assertThatThrownBy(()->service.assign("p",List.of(),0)).isInstanceOf(ApiException.class);verify(sets,never()).saveAndFlush(any());}
 @Test void firstAssignmentRevisionDiffersFromAbsentAndDoesNotMutateProduct(){var product=product("p",1,ProductVisibility.PUBLIC);product.setBasePrice(123);when(products.findById("p")).thenReturn(Optional.of(product));when(sets.findById("p")).thenReturn(Optional.empty());when(definitions.findAllById(List.of("new"))).thenReturn(List.of(marker("new",1,true,0)));when(sets.saveAndFlush(any())).thenAnswer(a->{ProductMarkerSet s=a.getArgument(0);s.version=0L;return s;});assertThat(service.assign("p",List.of("new"),0).version()).isEqualTo(1);assertThat(product.getBasePrice()).isEqualTo(123);verify(products,never()).save(any());}
 @Test void publicReadUsesSharedCatalogEligibilityAndExcludesDisabledAndForeignMarkers(){when(catalog.visibleProductOwners(null)).thenReturn(Map.of("a",1L));var set=new ProductMarkerSet();set.productId="a";set.merchantId=1L;set.markerIds=List.of("enabled","disabled","foreign");when(sets.findAllById(Set.of("a"))).thenReturn(List.of(set));when(definitions.findAllById(set.markerIds)).thenReturn(List.of(marker("enabled",1,true,20),marker("disabled",1,false,0),marker("foreign",2,true,0)));var result=service.publicAssignments(List.of("a","b","c"));assertThat(result).hasSize(1);assertThat(result.get(0).markers()).extracting(ProductMarkerService.Definition::id).containsExactly("enabled");verifyNoInteractions(users,products);}
 @Test void markedSectionRetainsAllSharedEligibleReferenceMastersBeyondOneBatch(){var owners=new LinkedHashMap<String,Long>();var assigned=new ArrayList<ProductMarkerSet>();for(int n=0;n<225;n++){String id="reference-"+n;owners.put(id,1L);var s=new ProductMarkerSet();s.productId=id;s.merchantId=1L;s.markerIds=List.of("new");assigned.add(s);}when(catalog.visibleProductOwners(1L)).thenReturn(owners);when(sets.findAllById(any())).thenAnswer(a->{Set<String> ids=new HashSet<>();((Iterable<String>)a.getArgument(0)).forEach(ids::add);return assigned.stream().filter(s->ids.contains(s.productId)).toList();});when(definitions.findAllById(List.of("new"))).thenReturn(List.of(marker("new",1,true,0)));assertThat(service.markedProductIds(1L)).hasSize(225);verify(catalog,times(1)).visibleProductOwners(1L);verifyNoInteractions(products);}
 @Test void definitionCodeAndVersionCannotBeOverwritten(){var d=marker("d",1,true,0);d.version=2L;when(definitions.findById("d")).thenReturn(Optional.of(d));assertThatThrownBy(()->service.save("d",new ProductMarkerService.Input("new","新",d.name,Map.of(),"green",0,true,1L))).isInstanceOf(ApiException.class);assertThatThrownBy(()->service.save("d",new ProductMarkerService.Input("renamed","新",d.name,Map.of(),"green",0,true,2L))).isInstanceOf(ApiException.class);verify(definitions,never()).saveAndFlush(any());}
 @Test void defaultBootstrapIsIdempotentAndNeverMarksAnyProduct(){for(var c:List.of("new","discount","low","missing"))when(definitions.findByMerchantIdAndCode(1L,c)).thenReturn(Optional.of(marker(c,1,true,0)));when(definitions.findByMerchantIdOrderBySortOrderAscIdAsc(1L)).thenReturn(List.of());service.defaults();service.defaults();verify(definitions,never()).saveAndFlush(any());verifyNoInteractions(products,sets);}
}
